export const Q = {
  /** L7–L9: title page: Umweltkennzeichnungen und -deklarationen — Umweltbezogene Anbietererklärungen (Umweltkennzeichnung Typ II) (ISO 14021:2016); Deutsche und Englische Fassung EN ISO 14021:2016 */
  L7_9: "Umweltkennzeichnungen und -deklarationen Umweltbezogene Anbietererklärungen (Umweltkennzeichnung Typ II) \\\\\n(ISO 14021:2016); \\\\\nDeutsche und Englische Fassung EN ISO 14021:2016 \\\\",
  /** L757: §5.1 the Clause-5 requirements apply to every self-declared claim, selected or "sonstige Umweltaussage" (the `other` token) */
  L757: "Die in Abschnitt 5 aufgeführten Anforderungen gelten für sämtliche umweltbezogenen Anbietererklärungen, unabhängig davon, ob es eine von den ausgewählten Aussagen ist, auf die in Abschnitt 7 verwiesen wird, oder eine sonstige Umweltaussage.",
  /** L781: §5.3 heading */
  L781: "\\subsection*{5.3 Unbestimmte oder unspezifische Aussagen}",
  /** L783: §5.3 vague / non-specific claims "darf nicht gemacht werden" */
  L783: "Eine unbestimmte oder unspezifische Umweltaussage oder eine, die allgemein darauf abzielt, dass ein Produkt günstig für die Umwelt oder umweltverträglich ist, darf nicht gemacht werden. Deshalb dürfen keine Umweltaussagen wie „umweltsicher“, „umweltfreundlich“, „freundlich zur Erde\", „ohne Emissionen“, „grün“, „naturfreundlich\" und „ozonfreundlich“ verwendet werden.",
  /** L787: §5.4 heading */
  L787: "\\subsection*{5.4 Aussagen von „... frei“}",
  /** L789: §5.4 "… frei" claims "darf nur gemacht werden, wenn …" */
  L789: "Eine Aussage von „... frei“ darf nur gemacht werden, wenn der Anteil des bestimmten Stoffes nicht größer ist als der, der als anerkannte Spurenverunreinigung oder natürliche Grundbelastung vorzufinden wäre.",
  /** L793: §5.5 heading */
  L793: "\\subsection*{5.5 Aussagen zur Nachhaltigkeit}",
  /** L795: §5.5 sustainability: "darf keine Aussage über das Erreichen von Nachhaltigkeit gemacht werden" */
  L795: "Konzepte im Zusammenhang mit Nachhaltigkeit sind äußerst kompliziert und werden noch untersucht. Gegenwärtig gibt es keine bestimmten Verfahren zur Messung von Nachhaltigkeit oder zu ihrer Bestätigung. Deshalb darf keine Aussage über das Erreichen von Nachhaltigkeit gemacht werden.",
  /** L797: §5.6 heading */
  L797: "\\subsection*{5.6 Anwendung von ergänzenden Erklärungen}",
  /** L799: §5.6 explanatory statements "müssen mit einer ergänzenden Erklärung verbunden sein, wenn …" */
  L799: "Umweltbezogene Anbietererklärungen müssen mit einer ergänzenden Erklärung verbunden sein, wenn die Aussage allein möglicherweise zu Missverständnissen führen kann. Eine Umweltaussage darf nur dann ohne ergänzende Erklärung erfolgen, wenn sie unter allen vorhersehbaren Umständen ohne Einschränkungen gültig ist.",
  /** L821: §5.7 heading */
  L821: "\\subsection*{5.7 Besondere Anforderungen}",
  /** L823: §5.7 intro: claims incl. every explanatory statement are subject to all of 5.7 */
  L823: "Umweltbezogene Anbietererklärungen und ergänzende Erklärungen sind Gegenstand aller Anforderungen in 5.7. Derartige Aussagen, einschließlich jeder ergänzenden Erklärung:",
  /** L827: §5.7 d) the claim shows whether it applies to the complete product, a component, the packaging or a service element (prod claim_scope) */
  L827: "d) müssen in einer Weise dargestellt werden, die eindeutig zeigt, ob die Aussage für das gesamte Produkt, nur für einen Teil des Produktes, die Verpackung oder einen Teil einer Dienstleistung gilt;",
  /** L855: §5.7 n) comparative claims: specific, basis of comparison, how recent the improvement is */
  L855: "n) müssen, wenn eine vergleichende Aussage von Umweltüberlegenheit oder -verbesserung gemacht wird, spezifisch sein und die Grundlage des Vergleichs verdeutlichen. Insbesondere muss die Umweltaussage darlegen, wie aktuell die Verbesserung ist;",
  /** L873: §5.8 heading */
  L873: "\\subsection*{5.8 Verwendung von Symbolen für Umweltaussagen}",
  /** L874: §5.8.1 the use of a symbol is optional */
  L874: "5.8.1 Wenn eine umweltbezogene Anbietererklärung gemacht wird, ist die Verwendung eines Symbols freigestellt.",
  /** L876: §5.8.3 symbols easily distinguishable from other symbols (prod symbol_distinguishable) */
  L876: "5.8.3 Symbole für eine bestimmte Umweltaussage sollten von anderen Symbolen, einschließlich Symbolen für sonstige Umweltaussagen, leicht zu unterscheiden sein.",
  /** L878: §5.8.5 natural objects only with a direct, verifiable link (prod natural_object_link) */
  L878: "5.8.5 Gegenstände aus der Natur dürfen nur abgebildet werden, wenn ein direkter und überprüfbarer Bezug zwischen Gegenstand und erklärtem Nutzen besteht.",
  /** L882: §5.9 heading */
  L882: "\\subsection*{5.9 Sonstige Informationen oder Aussagen}",
  /** L883: §5.9.1 words / numbers / symbols for material identification, disposal instructions, hazard warnings */
  L883: "5.9.1 Zusätzlich zu Umweltsymbolen dürfen Worte, Zahlen oder Symbole für Mitteilungen wie Materialkennzeichnung, Entsorgungshinweise oder Warnung vor Gefahren verwendet werden.",
  /** L900: §5.10 heading */
  L900: "\\subsection*{5.10 Spezifische Symbole}",
  /** L907: §5.10.2.1 the Möbius loop shall meet ISO 7000-1135 (prod REQ-48) */
  L907: "5.10.2.1 Das Drei-Pfeile-Symbol ist ein Symbol in Form von drei abgeknickten Pfeilen, die ein Dreieck bilden. Sobald es als Umweltaussage verwendet wird, muss dessen Ausführung die graphischen Anforderungen an ISO 7000-1135 erfüllen. Die Ausführung sollte jedoch ausreichend kontrastreich sein, damit das Symbol deutlich zu erkennen und unterscheidbar ist. Einige Ausführungsbeispiele des Drei-Pfeile-Symbols sind in Bild 1 dargestellt. Abschnitt 7 enthält detaillierte Anforderungen hinsichtlich Anwendung und Anwendbarkeit des Drei-Pfeile-Symbols.",
  /** L908: §5.10.2.2 product or packaging — explanatory statement when confusable */
  L908: "5.10.2.2 Das Drei-Pfeile-Symbol darf sich auf das Produkt oder die Verpackung beziehen. Besteht die Möglichkeit einer Verwechslung, ob es für das Produkt oder die Verpackung gilt, muss das Symbol mit einer ergänzenden Erklärung versehen sein.",
  /** L910: §5.10.2.4 the Möbius loop only for recycled content and recyclability (7.7 / 7.8) */
  L910: "5.10.2.4 Das Drei-Pfeile-Symbol darf nur für Aussagen von Recyclatgehalt und Recyclingfähigkeit verwendet werden, wie es in 7.7 und 7.8 festgelegt ist.",
  /** L938: §6.2.1 evaluation measures before the claim: reliable, reproducible results */
  L938: "6.2.1 Bevor eine Aussage getroffen wird, müssen Bewertungsmaßstäbe aufgestellt werden, damit zuverlässige und reproduzierbare Ergebnisse erhalten werden, die zur Bestätigung der Aussage notwendig sind.",
  /** L939: §6.2.2 evaluation fully documented and retained while the product is on the market */
  L939: "6.2.2 Die Bewertung muss umfassend dokumentiert und die Dokumentation vom Antragsteller für die Offenlegung von Informationen, auf die in 6.5.2 verwiesen wird, aufbewahrt werden. Das muss für den Zeitraum erfolgen, in dem sich das Produkt auf dem Markt befindet, und für einen ausreichenden Zeitraum danach, wobei die Lebensdauer des Produktes zu berücksichtigen ist.",
  /** L958–L962: §6.3.1 comparative claims evaluated against a) – d) (prod comparison_basis) */
  L958_962: "6.3.1 Vergleichende Aussagen müssen im Hinblick auf einen oder mehrere der folgenden Punkte bewertet werden:\na) vorheriges Verfahren einer Organisation;\nb) vorheriges Produkt einer Organisation;\nc) Verfahren einer anderen Organisation; oder\nd) Produkt einer anderen Organisation.",
  /** L964–L966: §6.3.1 "Der Vergleich darf nur durchgeführt werden: …" (published standard / recognised method; comparable, current products) */
  L964_966: "Der Vergleich darf nur durchgeführt werden:\n- auf der Grundlage einer veröffentlichten Norm oder eines anerkannten Prüfverfahrens (siehe 6.4); und\n- in Bezug auf vergleichbare, gegenwärtige oder vor Kurzem in demselben Markt angebotene Produkte mit entsprechender Funktion von demselben oder einem anderen Anbieter.",
  /** L967–L970: §6.3.2 a) same units, b) same functional unit, c) "über einen angemessenen Zeitraum, gewöhnlich 12 Monate" */
  L967_970: "6.3.2 Vergleichende Aussagen, die Umweltaspekte des Produktlebensweges enthalten, müssen:\na) in denselben Maßeinheiten gemessen und berechnet sein;\nb) auf derselben Funktionseinheit beruhen; und\nc) über einen angemessenen Zeitraum, gewöhnlich 12 Monate, berechnet werden.",
  /** L1004: §6.3.5 improvements of product and packaging stated separately, never aggregated */
  L1004: "6.3.5 Verbesserungen in Bezug auf ein Produkt und dessen Verpackung müssen getrennt dargelegt und dürfen nicht gemeinsam angegeben werden.",
  /** L1008: §6.4 selection of methods: international standards > recognised standards > industry methods proven equivalent; claimant-developed when none exists */
  L1008: "Bewertungsverfahren und Verfahren zur Überprüfung von Aussagen müssen in der Reihenfolge Internationale Normen, anerkannte Normen internationaler Akzeptanz (diese können regionale oder nationale Normen sein) oder Verfahren von Industrie und Handel, die sich in einer Prüfung durch Dritte als gleichwertig erwiesen haben, durchgeführt werden. Existiert noch kein Verfahren, darf ein für Umweltfragen Verantwortlicher ein Verfahren entwickeln, das die übrigen Anforderungen von Abschnitt 6 erfüllt und anderen zur Überprüfung zur Verfügung steht.",
  /** L1030: §6.5.1 verifiable only without confidential business information; otherwise the claim shall not be made */
  L1030: "6.5.1 Eine umweltbezogene Anbietererklärung ist nur dann als überprüfbar zu betrachten, wenn eine derartige Überprüfung ohne Zugang zu vertraulichen Geschäftsangaben vorgenommen werden kann. Die Aussagen dürfen nicht erfolgen, wenn sie nur mithilfe vertraulicher Geschäftsangaben überprüft werden können.",
  /** L1032: §6.5.3 head: "Die Mindestangaben, die nach 6.2 zu dokumentieren und aufzubewahren sind, müssen Folgendes enthalten:" */
  L1032: "6.5.3 Die Mindestangaben, die nach 6.2 zu dokumentieren und aufzubewahren sind, müssen Folgendes enthalten:",
  /** L1033: §6.5.3 a) identification of the standard or method used */
  L1033: "a) Angabe der angewendeten Norm oder des angewendeten Verfahrens;",
  /** L1034: §6.5.3 b) documentary evidence if verification cannot be made by testing the finished product */
  L1034: "b) Dokumente/Unterlagen, falls die Überprüfung der Aussage nicht durch Prüfung des Endproduktes erfolgen kann;",
  /** L1035: §6.5.3 c) test results where necessary */
  L1035: "c) Prüfergebnisse für den Fall, dass diese zur Überprüfung der Aussage notwendig sind;",
  /** L1036: §6.5.3 d) name and address of the independent testing party */
  L1036: "d) bei Prüfung durch eine unabhängige Prüfstelle, deren Name und Adresse;",
  /** L1037: §6.5.3 e) evidence of conformity with 5.7 h) and 5.7 r) */
  L1037: "e) Nachweis, dass die Aussage mit den Anforderungen von 5.7 h ) und 5.7 r ) übereinstimmt;",
  /** L1038: §6.5.3 f) comparison: description of the method, the test results of those products, the assumptions */
  L1038: "f) sofern die umweltbezogene Anbietererklärung einen Vergleich mit anderen Produkten enthält, eine eindeutige Beschreibung des angewendeten Verfahrens, der Ergebnisse von Prüfungen dieser Produkte und alle Annahmen;",
  /** L1054: §6.5.3 g) evidence of continuing accuracy while on the market and a reasonable period thereafter */
  L1054: "g) Nachweis, dass die Bewertung des Antragstellers die Gewissheit bietet, dass die umweltbezogene Anbietererklärung während des Zeitraumes, für den das Produkt auf dem Markt angeboten wird, und für einen angemessenen Zeitraum danach weiterhin richtig ist, wobei die Lebensdauer des Produktes zu berücksichtigen ist.",
  /** L1059: §7.1.1 Clause 7 supplements the other clauses; like terms do not diminish the onus */
  L1059: "7.1.1 Abschnitt 7 gibt Erklärungen und Anwendungshinweise für ausgewählte, häufig in umweltbezogenen Anbietererklärungen verwendete Begriffe. Die Verantwortung des Antragstellers, den in diesem Abschnitt dargelegten Prinzipien zu folgen, darf nicht durch Verwendung ähnlicher Begriffe abgeschwächt werden. Abschnitt 7 ergänzt, ersetzt jedoch nicht die Anforderungen in anderen Abschnitten der vorliegenden Internationalen Norm.",
  /** L1063–L1074: §7.1 NOTE: the Clause-7 terms in alphabetical order (7.2 kompostierbar … 7.13 Abfallminderung) — the printed claim-type list (structure) */
  L1063_1074: "7.2 kompostierbar\n7.3 abbaubar\n7.4 zerlegbar konstruiert\n7.5 verlängertes Produktleben\n7.6 zurückgewonnene Energie\n7.7 recyclingfähig\n7.8 Recyclatgehalt\n7.9 reduzierter Energieverbrauch\n7.10 reduzierter Ressourcenverbrauch\n7.11 reduzierter Wasserverbrauch\n7.12 wiederverwendbar und nachfüllbar\n7.13 Abfallminderung",
  /** L1104–L1107: §7.2.2.1 compostable "darf nicht erfolgen, wenn …" a) – c) */
  L1104_1107: "7.2.2.1 Eine Aussage zur Kompostierbarkeit darf nicht erfolgen, wenn ein Produkt, eine Verpackung oder ein Produkt- oder Verpackungsbestandteil:\na) den Gesamtnutzen des Komposts als Bodenverbesserungsmittel negativ beeinflusst;\nb) zu irgendeinem Zeitpunkt der Zersetzung oder danach Stoffe in gefährlichen Konzentrationen an die Umwelt abgibt; oder\nc) die Zersetzungsgeschwindigkeit in derartigen Systemen, in denen das Produkt oder der Bestandteil möglicherweise kompostiert wird, beträchtlich verringert.",
  /** L1108–L1110: §7.2.2.2 compostable claims qualified: facility type a), which components b) */
  L1108_1110: "7.2.2.2 Alle Aussagen zur Kompostierbarkeit müssen eindeutig eingestuft werden:\na) Die Aussage muss festlegen, ob die Art der Kompostierungsanlage oder des Kompostierverfahrens, in der bzw. dem der angegebene Bestandteil kompostierbar ist, eine Kompostierungsanlage im häuslichen Bereich oder vor Ort oder eine zentrale Kompostierungsanlage ist, sofern das Produkt nicht in sämtlichen Arten von Kompostierungsanlagen kompostierbar ist; in diesem Fall ist keine Festlegung erforderlich.\nb) Falls nicht das gesamte Produkt kompostierbar ist, muss die Aussage eindeutig zu erkennen geben, welche Bestandteile kompostierbar sind. Falls vom Anwender des Produktes verlangt wird, diese Bestandteile abzutrennen, müssen klare Anweisungen gegeben werden, wie das zu bewerkstelligen ist.",
  /** L1155–L1157: §7.3.2.1 degradable: a) only relative to a specific test method (degree, duration, disposal circumstances); b) not when hazardous concentrations are released */
  L1155_1157: "7.3.2.1 Die folgenden Voraussetzungen beziehen sich auf alle Abbauarten, z. B. den biologischen und den Photoabbau.\na) Aussagen zur Abbaubarkeit dürfen nur in Bezug auf ein bestimmtes Prüfverfahren erfolgen, das den zu erreichenden Abbaugrad und die Testdauer einschließt, und sie müssen für die Umstände zutreffen, unter denen das Produkt oder die Verpackung voraussichtlich entsorgt wird.\nb) Es darf keine Aussage zur Abbaubarkeit für ein Produkt oder eine Verpackung oder einen Bestandteil eines Produktes oder einer Verpackung erfolgen, die Stoffe in gefährlichen Konzentrationen an die Umwelt abgeben.",
  /** L1192: §7.4.2.1 designed for disassembly: accompanied by an explanatory statement naming the components / parts */
  L1192: "7.4.2.1 Die Aussage für zerlegbar konstruiert muss mit einer erklärenden Stellungnahme verbunden sein, die die Bestandteile oder Einzelteile festlegt, die wiederzuverwenden, zu recyceln, zur Rückgewinnung von Energie zu nutzen oder auf bestimmte andere Weise vom anfallenden Abfall abzutrennen sind.",
  /** L1194: §7.4.2.3 who disassembles: purchaser / user or specialists */
  L1194: "7.4.2.3 Alle Aussagen darüber, dass ein Produkt zerlegbar konstruiert ist, müssen Angaben enthalten, ob die Zerlegung vom Käufer oder Anwender vorzunehmen ist oder ob es zur Zerlegung durch Spezialisten zurückzugeben ist.",
  /** L1214–L1216: §7.4.2.6 disassembly by the purchaser "darf nur erfolgen, wenn" a) no special tools / expertise, b) clear instructions */
  L1214_1216: "7.4.2.6 Die Aussage, dass ein Produkt so konstruiert ist, dass es von Käufern, potentiellen Käufern oder Anwendern zerlegt werden kann, darf nur erfolgen, wenn:\na) keine Spezialwerkzeuge oder Fachkenntnisse erforderlich sind; und\nb) klare Anweisungen zur Zerlegung, Wiederverwendung, Rückführung, Rückgewinnung oder Entsorgung der Einzelteile vorhanden sind.",
  /** L1250: §7.5.2.1 extended life: substantiated; a comparative claim ⇒ 6.3 applies */
  L1250: "7.5.2.1 Sämtliche Aussagen zum verlängerten Produktleben müssen dargelegt werden. Weil die Aussagen zum verlängerten Produktleben vergleichende Aussagen sind, müssen die Anforderungen von 6.3 erfüllt sein.",
  /** L1252: §7.5.2.3 extended life by durability: percentage and a measured value or supporting evidence */
  L1252: "7.5.2.3 Aussagen zum verlängerten Produktleben, die auf verbesserter Haltbarkeit des Produktes beruhen, müssen die verlängerte Lebensdauer oder die Verbesserung auf Prozentbasis und einen gemessenen Wert angeben (z. B. wiederholt auftretende Anzahl an Vorgängen bis zum Bruch) oder Beweise enthalten, die die Aussage stützen.",
  /** L1268: §7.6.2 recovered energy: the energy used shall meet a) – c) and be evaluated per 7.6.3 */
  L1268: "Damit die Aussage erfolgen kann, dass ein Produkt mit zurückgewonnener Energie produziert wurde, muss die verwendete Energie folgende Anforderungen erfüllen und nach 7.6.3 bewertet werden:",
  /** L1290–L1292: §7.6.2 a) – c): waste-to-energy definition, adverse effects controlled, type and quantity of waste stated */
  L1290_1292: "a) Energierückgewinnung aus Abfällen bezieht sich auf die Sammlung und Umwandlung von Abfallmaterial in Nutzenergie. Das schließt jegliche Sammlung und Umwandlung von Abfallmaterialien aus dem Bereich von Industrie, Haushalt, Gewerbe und öffentlichen Versorgungseinrichtungen ein.\nb) Bevor eine Aussage zur zurückgewonnenen Energie erfolgen kann, muss der Antragsteller sicherstellen, dass nachteilige Auswirkungen auf die Umwelt, die von dieser Tätigkeit ausgehen, unter Kontrolle sind.\nc) Art und Menge des zur Energierückgewinnung eingesetzten Abfalls müssen angegeben werden.",
  /** L1296–L1298: §7.6.3 a) "Die Aussage darf nur erfolgen, wenn R-E>0." b) net recovered energy expressed as follows */
  L1296_1298: "Die Bewertung muss nach Abschnitt 6 erfolgen. Außerdem muss die Abschätzung der zurückgewonnenen Energie in folgender Weise berechnet werden:\na) Die Aussage darf nur erfolgen, wenn $R-E>0$.\nb) Die Aussage zur zurückgewonnenen Nettoenergie muss wie folgt angegeben werden:",
  /** L1297: §7.6.3 a) the printed condition R-E>0 (prod REQ-20) */
  L1297: "a) Die Aussage darf nur erfolgen, wenn $R-E>0$.",
  /** L1300–L1303: §7.6.3 printed formula: Zurückgewonnene Nettoenergie (%) = (R-E) / ((R-E)+P) × 100 (prod EQ-01) */
  L1300_1303: "Zurückgewonnene Nettoenergie (\\%)\n$$\n\\frac{(R-E)}{(R-E)+P} \\times 100\n$$",
  /** L1305–L1308: §7.6.3 legend: P primary energy in manufacturing, R energy from the recovery process, E primary energy used to recover */
  L1305_1308: "Dabei ist\n$P$ Energiemenge aus Primärquellen, die beim Herstellungsverfahren zum Herstellen des Produktes eingesetzt wird;\n$R$ Energiemenge, die sich aus dem Prozess der Energierückgewinnung ergibt;\n$E$ Energiemenge aus Primärquellen, die für den Prozess der Energierückgewinnung eingesetzt wird, um die zurückgewonnene Energie zurückzugewinnen oder zu entnehmen.",
  /** L1336–L1340: §7.7.2 recyclable: without convenient collection facilities a) qualified claim, b) limited availability conveyed, c) "Recyclingfähig, wenn Einrichtungen vorhanden sind" not allowed */
  L1336_1340: "Falls keine Sammelstellen oder Sammeleinrichtungen für das Recycling des Produktes oder der Verpackung für einen angemessenen Anteil an Käufern, potentiellen Käufern oder Anwendern des Produktes in verkehrsgünstiger Lage zur Verfügung stehen, gilt Folgendes:\na) Es muss eine konkrete Aussage zur Recyclingfähigkeit erfolgen.\nb) Die konkrete Aussage muss in geeigneter Weise auf die begrenzte Verfügbarkeit von Sammelstellen und Sammeleinrichtungen hinweisen.\nc) Verallgemeinerte Bezeichnungen wie „Recyclingfähig, wenn Einrichtungen vorhanden sind\", die nicht auf die begrenzte Verfügbarkeit von Sammelstellen und Sammeleinrichtungen hinweisen, sind nicht zulässig.",
  /** L1343–L1344: §7.7.3.2 / 7.7.3.3 recyclable symbol = the Möbius loop WITHOUT a percentage */
  L1343_1344: "7.7.3.2 Wird für eine Aussage zur Recyclingfähigkeit ein Symbol verwendet, muss es wie in 5.10.2 beschrieben das Drei-Pfeile-Symbol sein.\n7.7.3.3 Als Aussage zur Recyclingfähigkeit muss das in 5.10.2 beschriebene Drei-PfeileSymbol ohne Prozentwert verwendet werden.",
  /** L1370–L1373: §7.7.4 evaluation: evidence a) collection systems, b) recycling facilities, c) the product is collected and recycled */
  L1370_1373: "Die Bewertung muss nach Abschnitt 6 erfolgen. Die Angaben, auf die in 6.5 verwiesen wird, müssen folgende Nachweise enthalten:\na) Die Sammel-, Sortier- und Transportsysteme zur Überführung der Materialien von der Herkunft bis zur Recyclingeinrichtung stehen in verkehrsgünstiger Lage für einen angemessenen Anteil an Käufern, potentiellen Käufern oder Anwendern des Produktes zur Verfügung.\nb) Die Recycling-Einrichtungen stehen zur Aufnahme der gesammelten Materialien zur Verfügung.\nc) Das Produkt, für das die Aussage gemacht wird, wird gesammelt und recycelt.",
  /** L1382: §7.8.1.1 a) recycled content = mass fraction; only pre-consumer and post-consumer material count */
  L1382: "Masseanteil des recycelten Materials in einem Produkt oder einer Verpackung. Als Recyclatgehalt dürfen in Übereinstimmung mit der folgenden Verwendung der Begriffe nur Abfälle vor Gebrauch und Abfälle nach Gebrauch in Betracht gezogen werden.",
  /** L1386: §7.8.1.1 1) pre-consumer material (Abfall vor Gebrauch) definition */
  L1386: "Material, das beim Herstellungsverfahren aus dem Abfallstrom abgetrennt wird. Nicht enthalten ist die Wiederverwendung von Materialien aus Nachbearbeitung, Nachschliff oder Schrott, die im Verlauf eines technischen Verfahrens entstehen und im selben Prozess wiederverwendet werden können.",
  /** L1412: §7.8.1.1 2) post-consumer material (Abfall nach Gebrauch) definition */
  L1412: "> Material aus Haushalten, gewerblichen und industriellen Einrichtungen oder Instituten (die Endverbraucher des Produktes sind), das nicht mehr länger für den vorgesehenen Zweck verwendet werden kann. Darin enthalten ist zurückgeführtes Material aus der Lieferkette.",
  /** L1416: §7.8.1.1 b) recycled material (recyceltes Material) definition */
  L1416: "Material, das aus zurückgewonnenem [verwertetem] Material mit Hilfe eines Herstellungsverfahrens aufbereitet und zu einem Endprodukt oder zu einem Bestandteil eines Endproduktes verarbeitet wurde.",
  /** L1420: §7.8.1.1 c) recovered [reclaimed] material definition */
  L1420: "Material, das andernfalls als Abfall entsorgt oder zur Energierückgewinnung verwendet worden wäre, stattdessen jedoch gesammelt und als Materialeinsatz zurückgewonnen [verwertet] und an Stelle von neuem Primärmaterial für ein Recycling- oder Herstellungsverfahren verwendet wird.",
  /** L1449–L1450: §7.8.2.1 the percentage of recycled material shall be stated; 7.8.2.2 product and packaging separately (prod REQ-21) */
  L1449_1450: "7.8.2.1 Erfolgt eine Aussage zum Recyclatgehalt, muss der prozentuale Anteil an recyceltem Material angegeben werden.\n7.8.2.2 Der prozentuale Anteil des Recyclats für Produkte und Verpackung muss einzeln angegeben und darf nicht zusammengefasst werden.",
  /** L1453–L1454: §7.8.3.1 / 7.8.3.2 recycled-content symbol = the Möbius loop WITH the percentage "X %", X per 7.8.4 as a whole number */
  L1453_1454: "7.8.3.1 Erfolgt eine Aussage zum Recyclatgehalt, ist die Verwendung eines Symbols freigestellt.\n7.8.3.2 Falls zur Aussage zum Recyclatgehalt ein Symbol verwendet wird, muss es das Drei-Pfeile-Symbol mit zugehörigem Prozentwert sein, angegeben als „ $X \\%{ }^{\\text {“ }}$, wobei $X$ der nach 7.8.4 berechnete, als ganze Zahl angegebene Recyclatgehalt ist. Der Prozentwert muss entweder innerhalb des Drei-Pfeile-Symbols oder außerhalb und in unmittelbarer Nähe des Drei-PfeileSymbols angeordnet werden. Beispiele von akzeptabler Anbringung des Prozentwertes sind in Bild 2 dargestellt. Das Drei-Pfeile-Symbol mit einem Prozentwert, angegeben als „ $X \\%^{\\prime \\prime}$, muss als eine Aussage des Recyclatgehaltes aufgefasst werden.",
  /** L1479–L1485: §7.8.4.1 printed formula X(%) = A / P × 100 with legend A mass of recycled material, P product mass (prod EQ-02) */
  L1479_1485: "7.8.4.1 Die Bewertung muss nach Abschnitt 6 erfolgen. Außerdem muss der Recyclatgehalt quantitativ als prozentualer Anteil, wie nachstehend berechnet, angegeben werden. Weil keine Verfahren für die direkte Bestimmung des Recyclatgehaltes in einem Produkt oder einer Verpackung verfügbar sind, muss die Masse des beim Recyclingverfahren erhaltenen Materials unter Berücksichtigung von Verlusten und sonstigen Resten verwendet werden.\n$X(\\%)=\\frac{A}{P} \\times 100$\nDabei ist\n$X$ Recyclatgehalt, in Prozent;\nA Masse des recycelten Materials;\n$P$ Produktmasse.",
  /** L1480: §7.8.4.1 the formula line X(%)=A/P×100 */
  L1480: "$X(\\%)=\\frac{A}{P} \\times 100$",
  /** L1508–L1509: §7.9.2.1 / 7.9.2.2 reduced energy consumption: substantiated, comparative ⇒ 6.3; use phase only */
  L1508_1509: "7.9.2.1 Alle Aussagen zum reduzierten Energieverbrauch müssen begründet sein. Weil der reduzierte Energieverbrauch eine vergleichende Aussage ist, müssen die Anforderungen von 6.3 erfüllt sein.\n7.9.2.2 Aussagen zum reduzierten Energieverbrauch müssen auf Reduzierung des Energieverbrauchs bei der Verwendung von Produkten und Dienstleistungen beruhen. Die Aussage darf keinen reduzierten Energieverbrauch bei den Verfahren zur Herstellung des Produktes einschließen.",
  /** L1548–L1555: §7.10.2.1 – 7.10.2.8 reduced resource use qualifications (percentage of reduction, 6.3, resource type in an explanatory statement, 12-month initial period, per resource) */
  L1548_1555: "7.10.2.1 Ressourcen betreffen zusätzlich zu Rohstoffen auch Energie und Wasser.\n7.10.2.2 Alle Aussagen zum reduzierten Ressourcenverbrauch müssen begründet sein.\n7.10.2.3 Reduzierungen des Ressourcenverbrauchs für Produkte und Verpackung müssen getrennt angegeben und dürfen nicht zusammengefasst werden.\n7.10.2.4 Aussagen zum reduzierten Ressourcenverbrauch müssen als Anteil der Reduzierung in Prozent (\\%) angegeben werden. Weil der reduzierte Ressourcenverbrauch eine vergleichende Aussage ist, müssen die Anforderungen von 6.3 erfüllt sein.\n7.10.2.5 Wenn Aussagen zum reduzierten Ressourcenverbrauch erfolgen, muss die Art der Ressource in einer ergänzenden Erklärung angegeben werden.\n7.10.2.6 Falls als Folge des behaupteten reduzierten Ressourcenverbrauchs eine Erhöhung des Verbrauchs anderer Ressourcen zu verzeichnen ist, muss der erhöhte Ressourcenverbrauch und prozentuale Anteil in einer ergänzenden Erklärung angegeben werden.\n7.10.2.7 Wurde für eine anfängliche Dauer von 12 Monaten eine Reduzierung des Ressourcenverbrauchs erzielt, darf eine Aussage auf einer Überschlagsrechnung des reduzierten Ressourcenverbrauchs beruhen, die sich auf Konstruktion oder Vertrieb von Produkten oder Produktionsverfahren stützt.\n7.10.2.8 Eine Änderung des Ressourcenverbrauchs muss für jede Ressource einzeln angegeben werden.",
  /** L1551: §7.10.2.4 reduced resource use stated as a percentage; comparative ⇒ 6.3 */
  L1551: "7.10.2.4 Aussagen zum reduzierten Ressourcenverbrauch müssen als Anteil der Reduzierung in Prozent (\\%) angegeben werden. Weil der reduzierte Ressourcenverbrauch eine vergleichende Aussage ist, müssen die Anforderungen von 6.3 erfüllt sein.",
  /** L1569–L1574: §7.10.3 printed formula U(%) = (I-N) / I × 100 with legend (prod EQ-03) */
  L1569_1574: "Die Bewertung muss nach Abschnitt 6 erfolgen. Mit Ausnahme der erlaubten Einschränkung in 7.10.2.7 muss außerdem die verbrauchte Ressource je Produktionseinheit ermittelt werden, indem der Bruttoeinsatz von Ressourcen während 12-monatiger Dauer durch die Bruttoproduktion des gleichen Zeitraumes dividiert wird. Der prozentuale Anteil ( $U \\%$ ) an reduziertem Ressourcenverbrauch muss nach folgender Gleichung bestimmt werden.\n$U(\\%)=\\frac{(I-N)}{I} \\times 100$\nDabei ist\n$U$ reduzierter Ressourcenverbrauch je Produktionseinheit, in Prozent;\n$I$ anfänglicher Ressourcenverbrauch, angegeben als verbrauchte Ressource je Produktionseinheit;\n$N$ neuer Ressourcenverbrauch, angegeben als verbrauchte Ressource je Produktionseinheit.",
  /** L1570: §7.10.3 the formula line U(%)=(I-N)/I×100 */
  L1570: "$U(\\%)=\\frac{(I-N)}{I} \\times 100$",
  /** L1585: §7.11.2.1 reduced water consumption: substantiated, comparative ⇒ 6.3 */
  L1585: "7.11.2.1 Alle Aussagen zum reduzierten Wasserverbrauch müssen begründet sein. Weil der reduzierte Wasserverbrauch eine vergleichende Aussage ist, müssen die Anforderungen von 6.3 erfüllt sein.",
  /** L1625: §7.12.2.1 reusable / refillable only when the product can be reused / refilled for its original purpose */
  L1625: "7.12.2.1 Es darf kein Produkt oder keine Verpackung als wiederverwendbar oder nachfüllbar bezeichnet werden, wenn das Produkt oder die Verpackung nicht für den ursprünglich vorgesehenen Zweck wiederverwendet oder nachgefüllt werden kann.",
  /** L1646–L1648: §7.12.2.2 reusable / refillable "darf nur erfolgen, wenn" a) collection programme, b) facilities / products */
  L1646_1648: "7.12.2.2 Eine Aussage, dass ein Produkt oder eine Verpackung wiederverwendbar oder nachfüllbar ist, darf nur erfolgen, wenn:\na) ein Programm zum Sammeln der gebrauchten Produkte oder Verpackungen vorhanden ist und wenn sie wiederverwendet oder nachgefüllt werden, oder\nb) Einrichtungen oder Produkte vorhanden sind, die es dem Käufer ermöglichen, Produkte oder Verpackungen wiederzuverwenden oder nachzufüllen.",
  /** L1649–L1652: §7.12.2.3 without convenient programmes / facilities: a) qualified claim, b) limited availability, c) "wenn Einrichtungen vorhanden sind" insufficient */
  L1649_1652: "7.12.2.3 Gibt es in dem Bereich, in dem Produkte vertrieben werden, für einen angemessenen Anteil an Käufern, potentiellen Käufern oder Anwendern des Produktes kein bequem erreichbares System zum Sammeln der gebrauchten Produkte oder Verpackungen oder stehen keine Einrichtungen zur Wiederverwendung oder zum Nachfüllen bequem erreichbar zur Verfügung, gilt Folgendes:\na) Es muss eine eindeutige Aussage zur Wiederverwendbarkeit und Nachfüllbarkeit gegeben werden.\nb) Die eindeutige Aussage muss in angemessener Form auf die begrenzte Verfügbarkeit von Sammelsystemen oder -einrichtungen hinweisen.\nc) Verallgemeinerte Bezeichnungen wie „Wiederverwendbar/nachfüllbar, wenn Einrichtungen vorhanden sind\", die nicht auf die begrenzte Verfügbarkeit von Sammelprogrammen oder -einrichtungen hinweisen, sind unzureichend.",
  /** L1683: §7.13.2.1 waste reduction: substantiated, comparative ⇒ 6.3 */
  L1683: "7.13.2.1 Alle Aussagen zur Abfallminderung müssen begründet sein. Weil Abfallminderung eine vergleichende Aussage ist, müssen die Anforderungen von 6.3 erfüllt sein.",
  /** L1717: §7.14.2 renewable material: sources regenerating at least as fast as depletion */
  L1717: "Wenn bei Primärrohstoffen Aussagen zur Erneuerbarkeit gemacht werden, müssen diese Materialien aus Quellen stammen, die sich mit einer Geschwindigkeit regenerieren, die gleich oder höher als die Geschwindigkeit des Abbaus ist.",
  /** L1719–L1721: §7.14.2 unqualified renewable claim only at 100 % renewable material; otherwise a) percentage by mass stated, b) product and packaging separately (prod REQ-22) */
  L1719_1721: "Eine uneingeschränkte Aussage zur Erneuerbarkeit ist nur zulässig, wenn das Produkt zu 100 \\% aus erneuerbarem Material besteht, wobei nur geringfügige Anteile an nicht erneuerbarem Material in diesem Material erlaubt sind. Andernfalls müssen Aussagen zur Erneuerbarkeit wie folgt eingeschränkt werden:\na) wenn eine Aussage zum Gehalt an erneuerbarem Material gemacht wird, muss der prozentuale Massenanteil von erneuerbarem Material angegeben werden;\nb) der prozentuale Anteil von erneuerbarem Material (Massenanteil) in Produkten und in Verpackungen muss getrennt angegeben werden und darf nicht zusammengefasst werden.",
  /** L1763: §7.15.2 unqualified renewable-energy claim only when 100 % of the energy is renewable (prod REQ-23) */
  L1763: "Eine uneingeschränkte Aussage zur erneuerbaren Energie ist nur zulässig, wenn 100 \\% der Energie erneuerbar ist. Andernfalls müssen Aussagen zur erneuerbaren Energie wie folgt eingeschränkt werden.",
  /** L1765: §7.15.2 when a share of the energy is renewable the percentage shall be clearly stated */
  L1765: "Wenn ein Anteil der Energie aus erneuerbaren Energiequellen stammt, muss der prozentuale Anteil eindeutig angegeben werden.",
  /** L1801: §7.16.1 no claim of achieving sustainability; unqualified "nachhaltig" / "Nachhaltigkeit" shall not be used */
  L1801: "Wie in 5.5 angeführt, darf keine Anbietererklärung über das Erreichen von Nachhaltigkeit abgegeben werden. Im vorliegenden Unterabschnitt wird nochmals betont, dass uneingeschränkte Anbietererklärungen zu „nachhaltig“ und „Nachhaltigkeit\" nicht verwendet werden dürfen.",
  /** L1845: §7.17.2.2 product carbon footprint quantified and communicated per ISO/TS 14067 (prod REQ-25 / REQ-49) */
  L1845: "Die Quantifizierung und Kommunikation von „Carbon Footprints“ von Produkten muss nach ISO/TS 14067 durchgeführt werden.",
  /** L1854: §7.17.3.2 carbon neutral: all GHG emissions of the product system reduced, removed or offset */
  L1854: "In Bezug auf ein Produkt setzt „CO2-neutral“ voraus, dass sämtliche Treibhausgasemissionen (siehe 3.1.9) aus allen Stufen des Produktlebensweges und innerhalb des festgelegten Produktsystems reduziert, entzogen oder durch ein System von Ausgleichen oder Gutschriften oder auf andere Weise berücksichtigt wurden.",
  /** L1856: §7.17.3.2 "Eine uneingeschränkte Aussage zu „CO2-neutral“ darf nicht gemacht werden." */
  L1856: "Eine uneingeschränkte Aussage zu „CO2-neutral“ darf nicht gemacht werden.",
  /** L1860–L1862: §7.17.3.3 carbon-neutral claims shall include a) footprint equals zero or b) which life-cycle stages were offset */
  L1860_1862: "Aussagen zur „ $\\mathrm{CO}_{2}$-Neutralität“ müssen Folgendes enthalten:\na) eine Erklärung, dass der „Carbon Footprint“ eines Produktes gleich null ist; oder\nb) eine eindeutige Erklärung darüber, für welche Abschnitte des Produktlebensweges ein Ausgleich erfolgte.",
  /** L1864: §7.17.3.3 carbon-neutral claims incl. offsets backed by a statement giving the carbon footprint and what was offset (prod REQ-24) */
  L1864: "Aussagen zur „CO2-Neutralität“, einschließlich Ausgleichen, müssen durch eine Erklärung abgesichert werden, in der der „Carbon Footprint“ angegeben wird und in der eindeutig erläutert wird, was ausgeglichen wurde, wobei sämtliche Einzelheiten des angewendeten Ausgleichssystems und Informationen anzugeben sind, die dem Käufer den Zugang zu Quellen für weitergehende Informationen ermöglichen, die das Ausgleichsprogramm erläutern.",
  /** L884: §5.9.2 words / numbers / symbols not intended as environmental claims shall not be usable as one */
  L884: "5.9.2 Worte, Zahlen oder Symbole, die nicht für Umweltaussagen vorgesehen sind, dürfen nicht so verwendet werden, dass sie möglicherweise als Umweltaussage missverstanden werden können.",
  /** L1384: §7.8.1.1 heading line: 1) Abfall vor Gebrauch (pre_consumer_material label) */
  L1384: "\\section*{1) Abfall vor Gebrauch}",
  /** L1410: §7.8.1.1 heading line: 2) Abfall nach Gebrauch (post_consumer_material label) */
  L1410: "\\section*{2) Abfall nach Gebrauch}",
  /** L1414: §7.8.1.1 heading line: b) Recyceltes Material (recycled_material label) */
  L1414: "\\section*{b) Recyceltes Material}",
  /** L1418: §7.8.1.1 heading line: c) Zurückgewonnenes [verwertetes] Material (recovered_reclaimed_material label) */
  L1418: "\\section*{c) Zurückgewonnenes [verwertetes] Material}",
  /** L1616: §7.12.1.1 heading line: Wiederverwendbar (reusable label) */
  L1616: "\\subsection*{7.12.1.1 Wiederverwendbar}",
  /** L1620: §7.12.1.2 heading line: Nachfüllbar (refillable label) */
  L1620: "\\subsection*{7.12.1.2 Nachfüllbar}",
  /** L1709: §7.14 heading line: Erneuerbares Material */
  L1709: "\\subsection*{7.14 Erneuerbares Material}",
  /** L1753: §7.15 heading line: Erneuerbare Energie */
  L1753: "\\subsection*{7.15 Erneuerbare Energie}",
  /** L1797: §7.16 heading line: Nachhaltig */
  L1797: "\\subsection*{7.16 Nachhaltig}",
  /** L1812: §7.17.2 heading line: „Carbon Footprint“ eines Produktes */
  L1812: "\\subsection*{7.17.2 „Carbon Footprint“ eines Produktes}",
  /** L1894: §7.17.3.4 carbon neutrality determined first on the carbon footprint (7.17.2.2), then the equivalent offsets; or a footprint of zero */
  L1894: "Die Bestimmung der „ $\\mathrm{CO}_{2}$-Neutralität“ muss zuerst auf der Berechnung des „Carbon Footprints\" (siehe 7.17.2.2) und dann auf der Anrechnung der zu den Emissionen des „Carbon Footprints\" äquivalenten Ausgleiche beruhen. Alternativ kann „ $\\mathrm{CO}_{2}$-Neutralität“ von einem Produkt erreicht werden, wenn dessen „Carbon Footprint\" null ist.",
} as const;
